-- version_id values match catalog V3 seed (opaque ids, no FK).
INSERT INTO articles (id, version_id, article_number, title, body, sort_order) VALUES
  ('01900000-0000-4000-8000-000000000101', '01900000-0000-4000-8000-000000000003', '1', 'Human dignity',
   'Human dignity shall be inviolable. To respect and protect it shall be the duty of all state authority.', 1),
  ('01900000-0000-4000-8000-000000000102', '01900000-0000-4000-8000-000000000003', '2', 'Personal freedoms',
   'Every person shall have the right to free development of his personality insofar as he does not violate the rights of others or offend against the constitutional order or the moral law.', 2),
  ('01900000-0000-4000-8000-000000000103', '01900000-0000-4000-8000-000000000003', '3', 'Equality before the law',
   'All persons shall be equal before the law. Men and women shall have equal rights.', 3),
  ('01900000-0000-4000-8000-000000000104', '01900000-0000-4000-8000-000000000003', '4', 'Freedom of faith and conscience',
   'Freedom of faith and of conscience, and freedom to profess a religious or philosophical creed, shall be inviolable.', 4),
  ('01900000-0000-4000-8000-000000000105', '01900000-0000-4000-8000-000000000003', '5', 'Freedom of expression',
   'Every person shall have the right freely to express and disseminate his opinions in speech, writing and pictures.', 5),
  ('01900000-0000-4000-8000-000000000106', '01900000-0000-4000-8000-000000000003', '20', 'Constitutional principles',
   'The Federal Republic of Germany is a democratic and social federal state. All state authority is derived from the people.', 6),
  ('01900000-0000-4000-8000-000000000107', '01900000-0000-4000-8000-000000000003', '79', 'Amendment of the Basic Law',
   'This Basic Law may be amended only by a law expressly amending or supplementing its text.', 7),
  ('01900000-0000-4000-8000-000000000108', '01900000-0000-4000-8000-000000000003', '146', 'Duration of the Basic Law',
   'This Basic Law, which since the achievement of the unity and freedom of Germany applies to the entire German people, shall cease to apply on the day on which a constitution freely adopted by the German people takes effect.', 8);

INSERT INTO articles (id, version_id, article_number, title, body, sort_order) VALUES
  ('01900000-0000-4000-8000-000000000201', '01900000-0000-4000-8000-000000000004', '1', 'Human dignity',
   'Human dignity shall be inviolable. To respect and protect it shall be the duty of all state authority. The German people therefore acknowledge inviolable and inalienable human rights as the basis of every community, of peace and of justice in the world.', 1),
  ('01900000-0000-4000-8000-000000000202', '01900000-0000-4000-8000-000000000004', '2', 'Personal freedoms',
   'Every person shall have the right to free development of his personality insofar as he does not violate the rights of others or offend against the constitutional order or the moral law. Every person shall have the right to life and physical integrity.', 2),
  ('01900000-0000-4000-8000-000000000203', '01900000-0000-4000-8000-000000000004', '3', 'Equality before the law',
   'All persons shall be equal before the law. Men and women shall have equal rights. No person shall be favoured or disfavoured because of sex, parentage, race, language, homeland and origin, faith, or religious or political opinions.', 3),
  ('01900000-0000-4000-8000-000000000204', '01900000-0000-4000-8000-000000000004', '4', 'Freedom of faith and conscience',
   'Freedom of faith and of conscience, and freedom to profess a religious or philosophical creed, shall be inviolable. The undisturbed practice of religion shall be guaranteed.', 4),
  ('01900000-0000-4000-8000-000000000205', '01900000-0000-4000-8000-000000000004', '5', 'Freedom of expression',
   'Every person shall have the right freely to express and disseminate his opinions in speech, writing and pictures and to inform himself without hindrance from generally accessible sources.', 5),
  ('01900000-0000-4000-8000-000000000206', '01900000-0000-4000-8000-000000000004', '16a', 'Right of asylum',
   'Persons persecuted on political grounds shall have the right of asylum.', 6),
  ('01900000-0000-4000-8000-000000000207', '01900000-0000-4000-8000-000000000004', '20', 'Constitutional principles',
   'The Federal Republic of Germany is a democratic and social federal state. All state authority is derived from the people. The legislature shall be bound by the constitutional order, the executive and the judiciary by law and justice.', 7),
  ('01900000-0000-4000-8000-000000000208', '01900000-0000-4000-8000-000000000004', '23', 'European Union',
   'With a view to establishing a united Europe, the Federal Republic of Germany shall participate in the development of the European Union that is committed to democratic, social and federal principles.', 8),
  ('01900000-0000-4000-8000-000000000209', '01900000-0000-4000-8000-000000000004', '79', 'Amendment of the Basic Law',
   'This Basic Law may be amended only by a law expressly amending or supplementing its text. Amendments to this Basic Law affecting the division of the Federation into Länder, their participation on principle in the legislative process, or the principles laid down in Articles 1 and 20 shall be inadmissible.', 9),
  ('01900000-0000-4000-8000-000000000210', '01900000-0000-4000-8000-000000000004', '146', 'Duration of the Basic Law',
   'This Basic Law, which since the achievement of the unity and freedom of Germany applies to the entire German people, shall cease to apply on the day on which a constitution freely adopted by the German people takes effect.', 10);
